CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE orgs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, settings jsonb NOT NULL DEFAULT '{"audioRetentionDays":30,"transcriptRetentionDays":90,"minutesRetentionDays":0,"userQuotaBytes":104857600,"defaultLanguage":"en"}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX single_org ON orgs ((true));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs(id), email text NOT NULL UNIQUE CHECK(email=lower(email)), display_name text NOT NULL, avatar_media_id uuid, role text NOT NULL DEFAULT 'member' CHECK(role IN ('admin','member')), password_hash text, oidc_subject text UNIQUE, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE spaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs(id), name text NOT NULL, slug text NOT NULL, description text NOT NULL DEFAULT '', visibility text NOT NULL DEFAULT 'open' CHECK(visibility IN ('open','private')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,slug));
CREATE TABLE space_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), space_id uuid NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(space_id,user_id));
CREATE TABLE media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs(id), owner_id uuid NOT NULL REFERENCES users(id), storage_key text NOT NULL UNIQUE, original_name text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), width int, height int, sha256 text NOT NULL, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), space_id uuid NOT NULL REFERENCES spaces(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, pinned boolean NOT NULL DEFAULT false, deleted_at timestamptz, meeting_id uuid UNIQUE, attachments jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX posts_feed ON posts(space_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX posts_search ON posts USING gin(to_tsvector('simple',body));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX comments_post ON comments(post_id,created_at);
CREATE INDEX comments_search ON comments USING gin(to_tsvector('simple',body));
CREATE TABLE reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_type text NOT NULL CHECK(target_type IN ('post','comment','message')), target_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id), emoji text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(target_type,target_id,user_id,emoji));
CREATE TABLE dm_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dm_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES dm_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), last_read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,user_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES dm_threads(id), sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, media_id uuid REFERENCES media(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_thread ON messages(thread_id,created_at DESC);
CREATE INDEX messages_search ON messages USING gin(to_tsvector('simple',body));
CREATE TABLE message_reads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL REFERENCES messages(id), user_id uuid NOT NULL REFERENCES users(id), read_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id,user_id));
CREATE TABLE meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs(id), space_id uuid NOT NULL REFERENCES spaces(id), uploader_id uuid NOT NULL REFERENCES users(id), reviewer_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, held_at timestamptz, language_hint text, status text NOT NULL DEFAULT 'uploaded' CHECK(status IN ('uploaded','transcribing','drafting','review','approved','published','failed')), audio_media_id uuid REFERENCES media(id), duration_s real, published_post_id uuid REFERENCES posts(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE doc_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings(id), kind text NOT NULL CHECK(kind IN ('transcribe','draft','render')), status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','done','failed')), attempts int NOT NULL DEFAULT 0, error text, locked_at timestamptz, locked_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,kind));
CREATE INDEX doc_jobs_queue ON doc_jobs(status,created_at) WHERE status IN ('queued','running');
CREATE FUNCTION transcript_plain_text(segments jsonb) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT COALESCE(string_agg(value->>'text',' '),'') FROM jsonb_array_elements(segments) $$;
CREATE TABLE transcripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL UNIQUE REFERENCES meetings(id), language text NOT NULL, segments jsonb NOT NULL, text text GENERATED ALWAYS AS (transcript_plain_text(segments)) STORED, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX transcripts_search ON transcripts USING gin(to_tsvector('simple',text));
CREATE TABLE minutes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings(id), version int NOT NULL, content jsonb NOT NULL, edited_by uuid REFERENCES users(id), approved_by uuid REFERENCES users(id), approved_at timestamptz, docx_media_id uuid REFERENCES media(id), md_media_id uuid REFERENCES media(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,version));
CREATE INDEX minutes_search ON minutes USING gin(to_tsvector('simple',content->>'summary'));
CREATE TABLE action_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings(id), minutes_version int NOT NULL, text text NOT NULL, owner_user_id uuid REFERENCES users(id), owner_text text, due_date date, evidence_start_s real, evidence_end_s real, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), raw text NOT NULL, parsed jsonb NOT NULL, verified_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX single_license ON licenses ((true));
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES orgs(id), actor_id uuid REFERENCES users(id), action text NOT NULL, target_type text, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}', ip text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_recent ON audit_log(created_at DESC);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, title text NOT NULL, href text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);
